package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FumaExpressionPrepareCliTest {
    @TempDir Path temp;
    private static final String HEADER="gene\ts1\ts2\ts3\ts4\ts5\n";
    private List<String> args(String output)throws Exception{
        Files.writeString(temp.resolve("raw.tsv"),HEADER+"ENSG1.7\t0\t3\t7\t100\t9999\nENSG2\t1\t1\t1\t1\t100\nENSG3\t0\t0\t0\t2\t0\nENSG4\t0\t0\t0\t0\t100\n");
        Files.writeString(temp.resolve("samples.tsv"),"sample\tlabel\ns4\tB\ns3\tA\ns1\tA\ns2\tA\n");Files.writeString(temp.resolve("labels.tsv"),"label\nB\nA\n");
        return new ArrayList<>(List.of("--method","prepare-expression","--matrix",temp.resolve("raw.tsv").toString(),"--format","tsv","--samples",temp.resolve("samples.tsv").toString(),"--labels",temp.resolve("labels.tsv").toString(),"--extra-samples","exclude","--build","synthetic-GRCh37","--annotation-id","annotation-v1","--expression-id","synthetic-v1","--gene-namespace","exact-ensembl","--units","tpm","--empty","error","--out",temp.resolve(output).toString()));
    }
    private int run(List<String> args){var all=new ArrayList<>(List.of("fuma-tools"));all.addAll(args);var err=new ByteArrayOutputStream();int code=JLinAlgCli.run(all.toArray(String[]::new),new PrintStream(new ByteArrayOutputStream()),new PrintStream(err));if(code!=0)assertTrue(err.toString().contains("ANALYSIS FAILED")||err.toString().contains("WORKFLOW FAILED"),err.toString());return code;}
    private static void set(List<String> a,String key,String value){a.set(a.indexOf("--"+key)+1,value);}
    private void failed(String name,String message)throws Exception{Path d=temp.resolve(name);assertFalse(Files.exists(d.resolve("log2.tsv")));assertTrue(Files.readString(d.resolve("WARNINGS.md")).contains(message));assertTrue(Files.exists(d.resolve("partial")));assertTrue(Files.readString(d.resolve("analysis-status.json")).contains("failed"));}
    @Test void publicCommandStreamsExactSelectedRowsAndRecordsAllExclusions()throws Exception{assertEquals(0,run(args("done")));Path d=temp.resolve("done");List<String> logs=Files.readAllLines(d.resolve("log2.tsv"));assertEquals(3,logs.size());assertEquals("ensg\tB\tA",logs.get(0));assertTrue(logs.get(1).startsWith("ENSG1.7\t"));assertTrue(logs.get(2).startsWith("ENSG3\t"));assertEquals(5,Files.readAllLines(d.resolve("gene-audit.tsv")).size());assertTrue(Files.readString(d.resolve("sample-selection.tsv")).contains("4\ts5\tfalse\tNA"));assertEquals("label\tsamples\nB\t1\nA\t3\n",Files.readString(d.resolve("label-samples.tsv")));assertTrue(Files.readString(d.resolve("WARNINGS.md")).contains("RAW-MEAN BOUNDARY"));assertTrue(Files.readString(d.resolve("WARNINGS.md")).contains("UNWEIGHTED"));assertTrue(Files.readString(d.resolve("manifest.yaml")).contains("input_sha256"));}
    @Test void propertyAverageAndSampleCenterAreDifferentForUnequalLabels()throws Exception{assertEquals(0,run(args("done")));assertEquals(List.of(1L,3L),AdmixtureInputs.json(temp.resolve("done/session.json"),1048576).get("label_sample_counts"));String[] row=Files.readAllLines(temp.resolve("done/gene-covariates.tsv")).get(1).split("\t");double b=Double.parseDouble(row[1]),a=Double.parseDouble(row[2]);assertEquals((a+b)/2,Double.parseDouble(row[3]),1e-15);String[] audit=Files.readAllLines(temp.resolve("done/gene-audit.tsv")).get(1).split("\t");assertEquals((3*a+b)/4,Double.parseDouble(audit[4]),1e-15);assertNotEquals(Double.parseDouble(audit[4]),Double.parseDouble(row[3]));}
    @Test void equivalentGctPreservesDescriptionsAndProducesIdenticalResources()throws Exception{var a=args("tsv");assertEquals(0,run(a));set(a,"format","gct12");set(a,"out",temp.resolve("gct").toString());String t=Files.readString(temp.resolve("raw.tsv"));var lines=t.lines().toList();var gct=new StringBuilder("#1.2\n4\t5\nName\tDescription\ts1\ts2\ts3\ts4\ts5\n");for(String row:lines.subList(1,lines.size()))gct.append(row.replaceFirst("\t","\tgene description\t")).append('\n');Files.writeString(temp.resolve("raw.gct"),gct);set(a,"matrix",temp.resolve("raw.gct").toString());assertEquals(0,run(a));for(String f:List.of("log2.tsv","norm.tsv","gene-covariates.tsv","sample-selection.tsv","label-samples.tsv"))assertEquals(-1,Files.mismatch(temp.resolve("tsv").resolve(f),temp.resolve("gct").resolve(f)));assertTrue(Files.readString(temp.resolve("gct/gene-audit.tsv")).contains("gene description"));}
    @Test void downstreamExpressionCommandConsumesPreparedMatricesWithoutFurtherTransformation()throws Exception{
        assertEquals(0,run(args("prepared")));Files.writeString(temp.resolve("symbols.tsv"),"ensg\tsymbol\nENSG1.7\tONE\nENSG3\tTHREE\n");Files.writeString(temp.resolve("query.txt"),"ENSG1.7\nENSG3\n");Files.writeString(temp.resolve("background.txt"),"ENSG1.7\nENSG3\n");Files.writeString(temp.resolve("deg.tsv"),"all\t2\tENSG1.7:ENSG3\nA.up\t1\tENSG1.7\nA.down\t1\tENSG3\nA.twoside\t2\tENSG1.7:ENSG3\n");
        var a=List.of("--method","expression","--build","synthetic-GRCh37","--annotation-id","annotation-v1","--expression-id","synthetic-v1","--deg-id","supplied-independent-v1","--symbols",temp.resolve("symbols.tsv").toString(),"--query",temp.resolve("query.txt").toString(),"--background",temp.resolve("background.txt").toString(),"--log2",temp.resolve("prepared/log2.tsv").toString(),"--norm",temp.resolve("prepared/norm.tsv").toString(),"--deg-sets",temp.resolve("deg.tsv").toString(),"--duplicates","error","--outside-query","error","--out",temp.resolve("expression").toString());assertEquals(0,run(a));assertTrue(Files.exists(temp.resolve("expression/DEG.txt")));assertTrue(Files.readString(temp.resolve("expression/WARNINGS.md")).contains("SUPPLIED PRECOMPUTED"));
    }
    @Test void invalidValuesEvenInExcludedColumnsFailWithoutCompletedResources()throws Exception{for(String value:List.of("NaN","Infinity","-1","")){String name="value-"+value.hashCode();var a=args(name);Files.writeString(temp.resolve("raw.tsv"),HEADER+"G\t1\t2\t3\t4\t"+value+"\n");assertEquals(2,run(a));failed(name,"ANALYSIS FAILED");}}
    @Test void duplicateGenesWrongWidthsAndMalformedUtf8AreRejected()throws Exception{for(int i=0;i<3;i++){String name="malformed-"+i;var a=args(name);if(i==0)Files.writeString(temp.resolve("raw.tsv"),HEADER+"G\t1\t2\t3\t4\t0\nG\t2\t3\t4\t5\t0\n");if(i==1)Files.writeString(temp.resolve("raw.tsv"),HEADER+"G\t1\t2\n");if(i==2)Files.write(temp.resolve("raw.tsv"),new byte[]{(byte)0xc3,0x28});assertEquals(2,run(a));failed(name,"ANALYSIS FAILED");}}
    @Test void selectionsUnknownSamplesAndUndeclaredOrUnusedLabelsFail()throws Exception{for(int i=0;i<5;i++){String name="selection-"+i;var a=args(name);if(i==0)set(a,"extra-samples","error");if(i==1)Files.writeString(temp.resolve("samples.tsv"),"sample\tlabel\nunknown\tB\ns1\tA\n");if(i==2)Files.writeString(temp.resolve("samples.tsv"),"sample\tlabel\ns1\tB\ns1\tA\n");if(i==3)Files.writeString(temp.resolve("labels.tsv"),"label\nB\nA\nunused\n");if(i==4)Files.writeString(temp.resolve("labels.tsv"),"label\nB\nAverage\n");assertEquals(2,run(a));failed(name,"ANALYSIS FAILED");}}
    @Test void gctDimensionsAndExactHeaderAreEnforced()throws Exception{for(String content:List.of("#1.3\n4\t5\n","#1.2\n1\t4\nName\tDescription\ts1\ts2\ts3\ts4\ts5\n","#1.2\n2\t5\nName\tDescription\ts1\ts2\ts3\ts4\ts5\nG\tx\t1\t2\t3\t4\t0\n","#1.2\n1\t5\nName\twrong\ts1\ts2\ts3\ts4\ts5\n")){String name="gct-"+content.hashCode();var a=args(name);set(a,"format","gct12");Files.writeString(temp.resolve("raw.tsv"),content);assertEquals(2,run(a));failed(name,"ANALYSIS FAILED");}}
    @Test void emptyOutputRequiresExplicitPolicyAndRetainsCompleteAudit()throws Exception{var a=args("empty-error");Files.writeString(temp.resolve("raw.tsv"),HEADER+"G\t1\t1\t1\t1\t999\n");assertEquals(2,run(a));failed("empty-error","No gene passed strict");set(a,"empty","retain");set(a,"out",temp.resolve("empty-retain").toString());assertEquals(0,run(a));assertEquals(1,Files.readAllLines(temp.resolve("empty-retain/log2.tsv")).size());assertTrue(Files.readString(temp.resolve("empty-retain/WARNINGS.md")).contains("EMPTY PREPARED RESOURCE"));}
    @Test void completeInputOutputValueLineAndOwnedBudgetsFailWithoutPrefixes()throws Exception{for(String[] cap:new String[][]{{"max-genes","1"},{"max-values","1"},{"max-input-bytes","4"},{"max-output-bytes","10"},{"max-owned-bytes","65536"},{"max-line-bytes","16"}}){String name="budget-"+cap[0];var a=args(name);a.addAll(List.of("--"+cap[0],cap[1]));assertEquals(2,run(a));failed(name,"ANALYSIS FAILED");}}
    @Test void crlfUnicodeAndExactGeneVersionsArePreserved()throws Exception{var a=args("unicode-α");Files.writeString(temp.resolve("raw.tsv"),(HEADER+"ENSG1.17\t0\t3\t7\t100\t9999\n").replace("\n","\r\n"));assertEquals(0,run(a));assertTrue(Files.readString(temp.resolve("unicode-α/log2.tsv")).contains("ENSG1.17"));}
    @Test void existingOutputAndUnknownOptionsNeverOverwriteData()throws Exception{var a=args("existing");Files.createDirectory(temp.resolve("existing"));Files.writeString(temp.resolve("existing/keep"),"preserved");assertEquals(2,run(a));assertEquals("preserved",Files.readString(temp.resolve("existing/keep")));assertEquals(2,run(List.of("--method","prepare-expression","--unknown","x")));assertEquals(0,run(List.of("--method","prepare-expression","--help")));}
    private Map<String,Object> recipe()throws Exception{
        var source=args("unused");Map<String,String> preparation=new LinkedHashMap<>();for(int i=0;i<source.size();i+=2)preparation.put(source.get(i).substring(2),source.get(i+1));preparation.remove("method");preparation.remove("out");for(String k:List.of("matrix","samples","labels"))preparation.put(k,Path.of(preparation.get(k)).getFileName().toString());
        Files.writeString(temp.resolve("symbols.tsv"),"ensg\tsymbol\nENSG1.7\tONE\nENSG3\tTHREE\n");Files.writeString(temp.resolve("query.txt"),"ENSG1.7\nENSG3\n");Files.writeString(temp.resolve("background.txt"),"ENSG1.7\nENSG3\n");Files.writeString(temp.resolve("deg.tsv"),"all\t2\tENSG1.7:ENSG3\nA.up\t1\tENSG1.7\nA.down\t1\tENSG3\nA.twoside\t2\tENSG1.7:ENSG3\n");
        Map<String,String> expression=new LinkedHashMap<>(Map.of("symbols","symbols.tsv","query","query.txt","background","background.txt","deg-sets","deg.tsv","deg-id","supplied-independent-v1","duplicates","error","outside-query","error"));return new LinkedHashMap<>(Map.of("schema_version",1,"build","synthetic-GRCh37","expression_prepare",preparation,"expression",expression));
    }
    private int workflow(Map<String,Object> recipe,String output)throws Exception{Path p=temp.resolve("workflow-"+output+".json");Files.writeString(p,RegenieRuntime.json(recipe));return run(List.of("--method","workflow","--workflow-options-file",p.toString(),"--out",temp.resolve(output).toString()));}
    @Test void typedWorkflowPreparesAndPassesExactMatricesIntoExpression()throws Exception{assertEquals(0,workflow(recipe(),"workflow"));Path d=temp.resolve("workflow");assertTrue(Files.exists(d.resolve("expression-preparation/log2.tsv")));assertTrue(Files.exists(d.resolve("expression/log2-expression.tsv")));assertTrue(Files.exists(d.resolve("expression/DEG.txt")));assertTrue(Files.readString(d.resolve("expression/session.json")).contains("synthetic-v1"));assertTrue(Files.readString(d.resolve("manifest.json")).contains("expression-preparation"));}
    @Test void failedPreparationSkipsExpressionWithoutGeneratingFakeDegSets()throws Exception{var root=recipe();Files.writeString(temp.resolve("raw.tsv"),HEADER+"G\tNaN\t1\t2\t3\t0\n");assertEquals(2,workflow(root,"failed-workflow"));Path d=temp.resolve("failed-workflow");assertFalse(Files.exists(d.resolve("expression/DEG.txt")));assertTrue(Files.readString(d.resolve("expression/WARNINGS.md")).contains("Required stage expression-preparation did not complete"));assertEquals("all\t2\tENSG1.7:ENSG3\nA.up\t1\tENSG1.7\nA.down\t1\tENSG3\nA.twoside\t2\tENSG1.7:ENSG3\n",Files.readString(temp.resolve("deg.tsv")));}
    @Test void typedHandoffRejectsIdentityNamespaceAndMatrixOverrides()throws Exception{for(String field:List.of("expression-id","annotation-id","log2","norm")){var root=recipe();var expression=new LinkedHashMap<Object,Object>((Map<?,?>)root.get("expression"));expression.put(field,"conflicting");root.put("expression",expression);String name="conflict-"+field;assertEquals(2,workflow(root,name));assertFalse(Files.exists(temp.resolve(name)));}var root=recipe();var preparation=new LinkedHashMap<Object,Object>((Map<?,?>)root.get("expression_prepare"));preparation.put("gene-namespace","entrez");root.put("expression_prepare",preparation);assertEquals(2,workflow(root,"namespace"));assertFalse(Files.exists(temp.resolve("namespace")));}
    @Test void preparationCanRunAsIndependentTypedStage()throws Exception{var root=recipe();root.remove("expression");assertEquals(0,workflow(root,"preparation-only"));assertTrue(Files.exists(temp.resolve("preparation-only/expression-preparation/gene-covariates.tsv")));assertFalse(Files.exists(temp.resolve("preparation-only/expression")));}
    @Test void extremeFiniteInputsRetainExplicitRDepartureWarning()throws Exception{var a=args("extreme");Files.writeString(temp.resolve("raw.tsv"),HEADER+"G\t"+Double.MAX_VALUE+"\t"+Double.MAX_VALUE+"\t"+Double.MAX_VALUE+"\t"+Double.MAX_VALUE+"\t0\n");assertEquals(0,run(a));String w=Files.readString(temp.resolve("extreme/WARNINGS.md"));assertTrue(w.contains("EXTREME RAW EXPRESSION"));assertTrue(w.contains("numerical departure"));assertTrue(w.contains("check the source measurement units"));}
}
